        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(activeChannelId, messageSkip, PageSize);
        messages.InsertRange(0, older);
        messageSkip += older.Count;
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var sent = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(sent);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        // Update thread summary
        threadSummaries = GetThreadSummaries();
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh messages to show updated reactions
        messages = await ChatService.GetMessagesAsync(activeChannelId, 0, messageSkip > 0 ? messageSkip : PageSize);
    }

    private List<ThreadSummary> GetThreadSummaries()
    {
        // Build thread summaries from messages that have replies
        var rootIds = messages.Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
        return rootIds;
    }
